  public void Navigate(string key){if(key!=currentPage&&SectionNames.Root(pet.P,key)=="daily")ritimFilter="all";currentPage=key;categoryBack.Visibility=SectionNames.Parent(pet.P,key)!=""?Visibility.Visible:Visibility.Collapsed;ApplyPagePalette(key);saveSettings.Visibility=key=="settings"?Visibility.Visible:Visibility.Collapsed;page.Children.Clear();foreach(var pair in navigation){bool selected=pair.Key==SectionNames.Root(pet.P,key);pair.Value.Background=UI.B(selected?UI.InkColor:UI.SoftColor);pair.Value.Foreground=selected?UI.B(UI.PaperColor):UI.Ink;}switch(key){case "daily":Ritim("daily");break;case "home":Home();break;case "care":Care();break;case "shopping":shoppingSection="";Shopping();break;case "settings":PreferencesPage();break;case "drinks":DrinksPage();break;case "products":ProductsPage();break;case "supplements":SupplementsPage();break;case "measurements":MeasurementsPage();break;case "weekly":ReportPage(false);break;case "monthly":ReportPage(true);break;default:if(SectionNames.Parent(pet.P,key)=="shopping"){shoppingSection=key;Shopping();}else if(SectionNames.Root(pet.P,key)=="daily")Ritim(key);else Routine(key);break;}UpdateReportMenu();RecolorChrome();scroll.ScrollToTop();}
