  void EditTask(Reminder existing,string group){var editor=new ReminderEditor(this,existing,group);if(editor.ShowDialog()==true){if(existing==null){editor.Value.Order=pet.P.Reminders.Where(x=>x.Group==group).Select(x=>x.Order).DefaultIfEmpty(0).Max()+10;pet.P.Reminders.Add(editor.Value);}else{var v=editor.Value;existing.Title=v.Title;existing.Quantity=v.Quantity;existing.Message=v.Message;existing.Time=v.Time;existing.EveryMinutes=v.EveryMinutes;existing.WeekdaysOnly=v.WeekdaysOnly;existing.Icon=v.Icon;existing.NoNotification=v.NoNotification;existing.Enabled=v.Enabled;existing.LastTriggered="";}pet.Save();RefreshToday();}else if(editor.Delete&&existing!=null){pet.P.Reminders.Remove(existing);pet.Save();RefreshToday();}}
