 public static class IconPicker {
  public static ComboBox Create(string key){var combo=new ComboBox{FontSize=13,Padding=new Thickness(6),Margin=new Thickness(0,5,0,12)};for(int i=0;i<CuteIcons.Keys.Length;i++){var row=new StackPanel{Orientation=Orientation.Horizontal};row.Children.Add(CuteIcons.Create(CuteIcons.Keys[i],26));var text=UI.Text(CuteIcons.Labels[i],13);text.VerticalAlignment=VerticalAlignment.Center;text.Margin=new Thickness(9,0,0,0);row.Children.Add(text);combo.Items.Add(new ComboBoxItem{Content=row,Tag=CuteIcons.Keys[i]});}int selected=Array.IndexOf(CuteIcons.Keys,key);combo.SelectedIndex=selected<0?11:selected;return combo;}
  public static string Key(ComboBox combo){return (string)((ComboBoxItem)combo.SelectedItem).Tag;}
 }
